from collections import defaultdict

def find_permutation(n, p):
    visited = [False] * (n + 1)
    q = [0] * (n + 1)

    for i in range(1, n + 1):
        if not visited[i]:
            cycle = []
            x = i
            while not visited[x]:
                visited[x] = True
                cycle.append(x)
                x = p[x]

            if len(cycle) % 2 != 0:
                return [-1]

            mid = len(cycle) // 2
            for j in range(mid):
                q[cycle[j]] = cycle[(j + mid) % len(cycle)]
            for j in range(mid, len(cycle)):
                q[cycle[j]] = cycle[(j - mid) % len(cycle)]

    return q[1:]

def main():
    import sys
    input = sys.stdin.read
